    width = observation.get("grid_width", observation.get("width", 0))
    height = observation.get("grid_height", observation.get("height", 0))
    my = observation.get("self_position", observation.get("your_position", (0, 0)))
    opp = observation.get("opponent_position", observation.get("enemy_position", (0, 0)))
    resources = observation.get("resources", [])
    obstacles = observation.get("obstacles", [])
    # normalize
    try:
        x, y = int(my[0]), int(my[1])
    except Exception:
        x, y = 0, 0

    def in_bounds(nx, ny):
        if width and height:
            return 0 <= nx < width and 0 <= ny < height
        return True

    # build candidate moves: stay or 4-neighbors
    moves = [(0,0), (1,0), (-1,0), (0,1), (0,-1)]
    best = None
    best_score = -10**9

    # helper: Manhattan distance
    def md(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    # resource target
    target_r = None
    best_rd = 10**9
    for r in resources:
        try:
            rx, ry = int(r[0]), int(r[1])
        except Exception:
            continue
        d = md((x,y), (rx,ry))
        if d < best_rd:
            best_rd = d
            target_r = (rx,ry)

    for dx, dy in moves:
        nx, ny = x+dx, y+dy
        if not in_bounds(nx, ny):
            continue
        # avoid obstacles roughly
        if obstacles and (nx, ny) in [(o[0], o[1]) for o in obstacles]:
            continue
        score = 0
        if target_r is not None:
            score -= md((nx,ny), target_r)
        # prefer getting closer to opponent to contest
        score -= md((nx,ny), opp)
        # small bonus for staying put
        if dx==0 and dy==0:
            score += 0
        if score > best_score:
            best_score = score
            best = (dx, dy)

    if best is None:
        return [0, 0]
    return [best[0], best[1]]

